// Mapema public site Worker. Generated by scripts/build-site.mjs, which embeds apps/web/out and the notice version.
const FILES = __FILES__;
const PRIVACY_NOTICE_VERSION = __NOTICE__;
const SEC = {
  'Content-Security-Policy': "default-src 'self'; connect-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'",
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'strict-origin-when-cross-origin',
  'Permissions-Policy': 'camera=(), microphone=(), geolocation=()',
  'Strict-Transport-Security': 'max-age=31536000; includeSubDomains',
  'X-Robots-Tag': 'noindex',
};
const EMAIL = /^[^\s@<>()",;:]{1,64}@[A-Za-z0-9.-]{1,190}\.[A-Za-z]{2,24}$/;
const PHONE = /^\+254[17][0-9]{8}$/;
const DSR_TYPES = ['access', 'correction', 'deletion', 'objection', 'portability', 'restriction'];

const json = (status, body) => new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store', ...SEC } });
const file = (f, status, extra) => new Response(f[1], { status, headers: { 'Content-Type': f[0], ...SEC, ...extra } });
const str = (v, max, required = true) => {
  if (v === undefined || v === null || v === '') return required ? null : '';
  if (typeof v !== 'string') return null;
  const s = v.trim().replace(/[\u0000-\u001f\u007f]/g, ' ');
  return (required && !s) || s.length > max ? null : s;
};
const lang = (v) => (v === 'sw' ? 'sw' : 'en');
const newId = () => crypto.randomUUID();
const ref = (id) => id.slice(0, 8).toUpperCase();

async function readBody(request, url) {
  const origin = request.headers.get('Origin');
  if (origin && origin !== url.origin) return { err: json(403, { error: 'origin' }) };
  if (!(request.headers.get('Content-Type') || '').toLowerCase().startsWith('application/json')) return { err: json(415, { error: 'content_type' }) };
  const text = await request.text();
  if (text.length > 8192) return { err: json(413, { error: 'too_large' }) };
  try { const b = JSON.parse(text); if (b && typeof b === 'object' && !Array.isArray(b)) return { body: b }; } catch { /* fall through */ }
  return { err: json(400, { error: 'invalid_json' }) };
}

async function bookACall(b, env) {
  const contactName = str(b.contactName, 120), company = str(b.company, 200), email = str(b.email, 254), phone = str(b.phone, 20, false);
  const errors = [];
  if (!contactName) errors.push('contactName');
  if (!company) errors.push('company');
  if (!email || !EMAIL.test(email)) errors.push('email');
  if (phone === null || (phone && !PHONE.test(phone.replace(/\s/g, '')))) errors.push('phone');
  if (b.role !== 'buyer' && b.role !== 'supplier') errors.push('role');
  if (b.privacyNoticeAccepted !== true) errors.push('privacyNoticeAccepted');
  if (errors.length) return json(422, { error: 'invalid', fields: errors });
  const id = newId();
  await env.DB.prepare('INSERT INTO call_requests (id, created_at, contact_name, company, email, phone, role, privacy_notice_version, lang) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9)')
    .bind(id, new Date().toISOString(), contactName, company, email.toLowerCase(), phone ? phone.replace(/\s/g, '') : null, b.role, PRIVACY_NOTICE_VERSION, lang(b.lang)).run();
  return json(201, { ref: ref(id) });
}

async function dataRequest(b, env) {
  const email = str(b.email, 254), details = str(b.details, 1000, false);
  const errors = [];
  if (!email || !EMAIL.test(email)) errors.push('email');
  if (!DSR_TYPES.includes(b.type)) errors.push('type');
  if (details === null) errors.push('details');
  if (errors.length) return json(422, { error: 'invalid', fields: errors });
  const id = newId();
  await env.DB.prepare('INSERT INTO data_requests (id, created_at, email, type, details, privacy_notice_version, lang) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)')
    .bind(id, new Date().toISOString(), email.toLowerCase(), b.type, details || null, PRIVACY_NOTICE_VERSION, lang(b.lang)).run();
  return json(201, { ref: ref(id) });
}

const API = { '/api/book-a-call': bookACall, '/api/data-request': dataRequest };

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    let p = decodeURIComponent(url.pathname);
    if (API[p]) {
      if (request.method !== 'POST') return new Response('Method not allowed', { status: 405, headers: { Allow: 'POST', ...SEC } });
      const { body, err } = await readBody(request, url);
      if (err) return err;
      // Honeypot: people never see the "website" field; anything in it is a bot. Pretend success, store nothing.
      if (typeof body.website === 'string' && body.website.trim() !== '') return json(201, { ref: ref(newId()) });
      try { return await API[p](body, env); } catch (e) { console.error('store failed', String(e)); return json(500, { error: 'server' }); }
    }
    if (request.method !== 'GET' && request.method !== 'HEAD') return new Response('Method not allowed', { status: 405, headers: { Allow: 'GET, HEAD', ...SEC } });
    if (p.length > 1 && p.endsWith('/')) return Response.redirect(url.origin + p.slice(0, -1) + url.search, 308);
    if (p.endsWith('.html') && p !== '/404.html') return Response.redirect(url.origin + (p === '/index.html' ? '/' : p.slice(0, -5)) + url.search, 308);
    const f = FILES[p] || FILES[p === '/' ? '/index.html' : p + '.html'];
    if (f) return file(f, 200, { 'Cache-Control': p.startsWith('/_next/static/') ? 'public, max-age=31536000, immutable' : 'public, max-age=0, must-revalidate' });
    return file(FILES['/404.html'], 404, { 'Cache-Control': 'no-store' });
  },
};
